import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    open: true,
    host: true,
  },
  build: {
    target: 'es2020',
    sourcemap: false,
  },
})

{
  "compilerOptions": {
    "composite": true,
    "skipLibCheck": true,
    "module": "ESNext",
    "moduleResolution": "bundler",
    "allowSyntheticDefaultImports": true,
    "strict": true
  },
  "include": ["vite.config.ts"]
}

/** @type {import('tailwindcss').Config} */
export default {
  content: ['./index.html', './src/**/*.{js,ts,jsx,tsx}'],
  theme: {
    extend: {
      fontFamily: {
        display: ['Orbitron', 'system-ui', 'sans-serif'],
        sans: ['Inter', 'system-ui', 'sans-serif'],
      },
      colors: {
        neon: {
          pink: '#ff2d95',
          cyan: '#00f5ff',
          purple: '#b026ff',
          yellow: '#fffb00',
          green: '#39ff14',
        },
      },
      animation: {
        'pulse-glow': 'pulseGlow 2s ease-in-out infinite',
        'gradient-shift': 'gradientShift 8s ease infinite',
        'float': 'float 3s ease-in-out infinite',
        'scan-line': 'scanLine 4s linear infinite',
      },
      keyframes: {
        pulseGlow: {
          '0%, 100%': { opacity: 1, filter: 'drop-shadow(0 0 8px currentColor)' },
          '50%': { opacity: 0.85, filter: 'drop-shadow(0 0 18px currentColor)' },
        },
        gradientShift: {
          '0%, 100%': { backgroundPosition: '0% 50%' },
          '50%': { backgroundPosition: '100% 50%' },
        },
        float: {
          '0%, 100%': { transform: 'translateY(0)' },
          '50%': { transform: 'translateY(-8px)' },
        },
        scanLine: {
          '0%': { transform: 'translateY(-100%)' },
          '100%': { transform: 'translateY(100%)' },
        },
      },
    },
  },
  plugins: [],
}

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

// 核心类型定义

export type Point = { x: number; y: number };

export type Direction = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';

export type GameStatus = 'idle' | 'playing' | 'paused' | 'over';

export type GameMode = 'classic' | 'wall' | 'timed' | 'obstacles';

export type ThemeId = 'neon' | 'sunset' | 'ocean' | 'aurora';

export interface Theme {
  id: ThemeId;
  name: string;
  emoji: string;
  bg: string;          // 背景渐变
  grid: string;        // 网格颜色
  snakeHead: string;   // 蛇头
  snakeBody: string;   // 蛇身(渐变)
  snakeTail: string;   // 蛇尾
  food: string;        // 食物
  foodGlow: string;    // 食物辉光
  accent: string;      // UI 强调色
  particle: string;    // 粒子
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
  color: string;
}

export interface GameState {
  // 网格
  cols: number;
  rows: number;
  cellSize: number;

  // 蛇
  snake: Point[];
  direction: Direction;
  nextDirection: Direction;
  growPending: number;

  // 食物
  food: Point;

  // 障碍物(障碍模式)
  obstacles: Point[];

  // 游戏状态
  status: GameStatus;
  mode: GameMode;
  theme: ThemeId;

  // 计时
  score: number;
  highScore: number;
  level: number;
  speedMs: number;        // 每步毫秒
  timeLeft: number;       // 限时模式(秒)

  // 统计
  totalFood: number;
  startTime: number;
}

export interface GameActions {
  start: () => void;
  pause: () => void;
  resume: () => void;
  reset: () => void;
  setDirection: (d: Direction) => void;
  setMode: (m: GameMode) => void;
  setTheme: (t: ThemeId) => void;
  step: () => void;
  tickTime: (dt: number) => void;
}

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type {
  GameState,
  GameActions,
  Direction,
  GameMode,
  ThemeId,
  Point,
} from '../types';
import { generateObstacles } from '../game/food';

const COLS = 24;
const ROWS = 24;
const CELL_SIZE = 24; // 实际尺寸由 Canvas 自适应

const initialSnake = (): Point[] => [
  { x: 10, y: 12 },
  { x: 9, y: 12 },
  { x: 8, y: 12 },
];

const loadHighScore = (): number => {
  try {
    const raw = localStorage.getItem('neon-snake-highscore');
    return raw ? parseInt(raw, 10) || 0 : 0;
  } catch {
    return 0;
  }
};

const saveHighScore = (score: number) => {
  try {
    const cur = loadHighScore();
    if (score > cur) {
      localStorage.setItem('neon-snake-highscore', String(score));
    }
  } catch {
    /* noop */
  }
};

const opposite = (d: Direction): Direction => {
  switch (d) {
    case 'UP':
      return 'DOWN';
    case 'DOWN':
      return 'UP';
    case 'LEFT':
      return 'RIGHT';
    case 'RIGHT':
      return 'LEFT';
  }
};

const speedForLevel = (level: number): number => {
  // 等级越高越快(毫秒/步)
  return Math.max(60, 160 - level * 12);
};

export const useGameStore = create<GameState & GameActions>()(
  persist(
    (set, get) => ({
      cols: COLS,
      rows: ROWS,
      cellSize: CELL_SIZE,

      snake: initialSnake(),
      direction: 'RIGHT',
      nextDirection: 'RIGHT',
      growPending: 0,

      food: { x: 16, y: 12 },

      obstacles: [],

      status: 'idle',
      mode: 'classic',
      theme: 'neon',

      score: 0,
      highScore: loadHighScore(),
      level: 1,
      speedMs: speedForLevel(1),
      timeLeft: 60,

      totalFood: 0,
      startTime: 0,

      start: () => {
        const mode = get().mode;
        set({
          snake: initialSnake(),
          direction: 'RIGHT',
          nextDirection: 'RIGHT',
          growPending: 0,
          food: { x: 16, y: 12 },
          obstacles: mode === 'obstacles' ? generateObstacles(COLS, ROWS, initialSnake(), [{ x: 16, y: 12 }]) : [],
          status: 'playing',
          score: 0,
          level: 1,
          speedMs: speedForLevel(1),
          timeLeft: mode === 'timed' ? 60 : 0,
          totalFood: 0,
          startTime: Date.now(),
        });
      },

      pause: () => {
        if (get().status === 'playing') set({ status: 'paused' });
      },

      resume: () => {
        if (get().status === 'paused') set({ status: 'playing' });
      },

      reset: () => {
        set({ status: 'idle' });
      },

      setDirection: (d: Direction) => {
        const { direction, status } = get();
        if (status !== 'playing') return;
        // 不能 180° 反向
        if (opposite(direction) === d) return;
        set({ nextDirection: d });
      },

      setMode: (m: GameMode) => {
        if (get().status === 'playing') return;
        set({ mode: m, obstacles: m === 'obstacles' ? generateObstacles(COLS, ROWS, initialSnake(), [{ x: 16, y: 12 }]) : [] });
      },

      setTheme: (t: ThemeId) => set({ theme: t }),

      step: () => {
        const s = get();
        if (s.status !== 'playing') return;

        const dir = s.nextDirection;
        const head = s.snake[0];
        let nx = head.x;
        let ny = head.y;
        switch (dir) {
          case 'UP':
            ny -= 1;
            break;
          case 'DOWN':
            ny += 1;
            break;
          case 'LEFT':
            nx -= 1;
            break;
          case 'RIGHT':
            nx += 1;
            break;
        }

        // 穿墙模式: 环绕
        if (s.mode === 'wall') {
          if (nx < 0) nx = COLS - 1;
          if (nx >= COLS) nx = 0;
          if (ny < 0) ny = ROWS - 1;
          if (ny >= ROWS) ny = 0;
        }

        // 经典/限时/障碍: 撞墙即死
        if (s.mode !== 'wall' && (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS)) {
          saveHighScore(s.score);
          set({ status: 'over', direction: dir, highScore: Math.max(s.highScore, s.score) });
          return;
        }

        const newHead: Point = { x: nx, y: ny };

        // 撞自身
        const willGrow = (nx === s.food.x && ny === s.food.y) || s.growPending > 0;
        const bodyToCheck = willGrow ? s.snake : s.snake.slice(0, -1);
        if (bodyToCheck.some((p) => p.x === nx && p.y === ny)) {
          saveHighScore(s.score);
          set({ status: 'over', direction: dir, highScore: Math.max(s.highScore, s.score) });
          return;
        }

        // 撞障碍
        if (s.mode === 'obstacles' && s.obstacles.some((p) => p.x === nx && p.y === ny)) {
          saveHighScore(s.score);
          set({ status: 'over', direction: dir, highScore: Math.max(s.highScore, s.score) });
          return;
        }

        // 应用方向 & 移动
        const newSnake = [newHead, ...s.snake];
        if (!willGrow) {
          newSnake.pop();
        } else if (s.growPending > 0) {
          set({ growPending: s.growPending - 1 });
        }

        let newScore = s.score;
        let newLevel = s.level;
        let newSpeed = s.speedMs;
        let newFood = s.food;
        let newTotalFood = s.totalFood;
        let newGrow = 0;
        let newStatus: typeof s.status = s.status;

        if (nx === s.food.x && ny === s.food.y) {
          // 吃到食物
          newScore += 10;
          newTotalFood += 1;
          newGrow = 0; // 已经在 willGrow 中处理了
          // 每 5 个食物升一级
          if (newTotalFood % 5 === 0) {
            newLevel += 1;
            newSpeed = speedForLevel(newLevel);
          }
          // 生成新食物
          const occupied = [...newSnake, ...s.obstacles];
          let placed = false;
          for (let attempt = 0; attempt < 200 && !placed; attempt++) {
            const fx = Math.floor(Math.random() * COLS);
            const fy = Math.floor(Math.random() * ROWS);
            if (!occupied.some((p) => p.x === fx && p.y === fy)) {
              newFood = { x: fx, y: fy };
              placed = true;
            }
          }
        }

        // 限时模式: 时间到即结束
        if (s.mode === 'timed' && s.timeLeft <= 0) {
          saveHighScore(newScore);
          newStatus = 'over';
        }

        set({
          snake: newSnake,
          direction: dir,
          food: newFood,
          score: newScore,
          level: newLevel,
          speedMs: newSpeed,
          totalFood: newTotalFood,
          growPending: newGrow,
          highScore: Math.max(s.highScore, newScore),
          status: newStatus,
        });
      },

      tickTime: (dt: number) => {
        const s = get();
        if (s.status !== 'playing' || s.mode !== 'timed') return;
        const newTime = Math.max(0, s.timeLeft - dt);
        if (newTime <= 0) {
          saveHighScore(s.score);
          set({ timeLeft: 0, status: 'over', highScore: Math.max(s.highScore, s.score) });
        } else {
          set({ timeLeft: newTime });
        }
      },
    }),
    {
      name: 'neon-snake-storage',
      partialize: (state) => ({
        theme: state.theme,
        mode: state.mode,
        highScore: state.highScore,
      }),
    },
  ),
);

import type { Point } from '../types';

/**
 * 生成障碍物 - 在空地中随机撒一些点(避开初始蛇和食物)
 */
export function generateObstacles(
  cols: number,
  rows: number,
  snake: Point[],
  food: Point[],
): Point[] {
  const occupied: Point[] = [...snake, ...food];
  // 中心 8x8 区域不放障碍
  const centerStartX = Math.floor(cols / 2) - 4;
  const centerStartY = Math.floor(rows / 2) - 4;

  const candidates: Point[] = [];
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      if (x >= centerStartX && x < centerStartX + 8 && y >= centerStartY && y < centerStartY + 8) continue;
      if (occupied.some((p) => p.x === x && p.y === y)) continue;
      candidates.push({ x, y });
    }
  }

  // 打乱
  for (let i = candidates.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [candidates[i], candidates[j]] = [candidates[j], candidates[i]];
  }

  // 取约 12% 的格子
  const count = Math.floor(candidates.length * 0.12);
  return candidates.slice(0, count);
}

import type { Particle } from '../types';

const POOL_SIZE = 256;

class ParticlePool {
  pool: Particle[];
  alive: Particle[];

  constructor(size: number) {
    this.pool = [];
    this.alive = [];
    for (let i = 0; i < size; i++) {
      this.pool.push({
        x: 0,
        y: 0,
        vx: 0,
        vy: 0,
        life: 0,
        maxLife: 0,
        size: 0,
        color: '#fff',
      });
    }
  }

  spawn(particle: Omit<Particle, never>) {
    const p = this.pool.pop();
    if (!p) return;
    Object.assign(p, particle);
    this.alive.push(p);
  }

  update(dt: number) {
    for (let i = this.alive.length - 1; i >= 0; i--) {
      const p = this.alive[i];
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vx *= 0.96;
      p.vy *= 0.96;
      p.life -= dt;
      if (p.life <= 0) {
        this.alive.splice(i, 1);
        this.pool.push(p);
      }
    }
  }

  reset() {
    while (this.alive.length) {
      this.pool.push(this.alive.pop()!);
    }
  }
}

export const particlePool = new ParticlePool(POOL_SIZE);

/**
 * 在吃食物时爆发粒子
 */
export function emitFoodBurst(x: number, y: number, color: string, count = 24) {
  for (let i = 0; i < count; i++) {
    const angle = (Math.PI * 2 * i) / count + Math.random() * 0.4;
    const speed = 60 + Math.random() * 100;
    particlePool.spawn({
      x,
      y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      life: 0.4 + Math.random() * 0.5,
      maxLife: 0.9,
      size: 2 + Math.random() * 3,
      color,
    });
  }
}

/**
 * 蛇移动留下的尾迹粒子
 */
export function emitSnakeTrail(x: number, y: number, color: string) {
  particlePool.spawn({
    x: x + (Math.random() - 0.5) * 8,
    y: y + (Math.random() - 0.5) * 8,
    vx: (Math.random() - 0.5) * 20,
    vy: (Math.random() - 0.5) * 20,
    life: 0.3 + Math.random() * 0.3,
    maxLife: 0.6,
    size: 1.5 + Math.random() * 1.5,
    color,
  });
}

/**
 * 背景氛围粒子 - 缓慢上升
 */
export function emitAmbient(x: number, y: number, color: string) {
  particlePool.spawn({
    x,
    y,
    vx: (Math.random() - 0.5) * 8,
    vy: -10 - Math.random() * 10,
    life: 1.5 + Math.random() * 1.5,
    maxLife: 3,
    size: 1 + Math.random() * 1.5,
    color,
  });
}

import type { Point, Theme } from '../types';
import { THEMES } from './themes';
import type { Particle } from '../types';
import { particlePool } from './particles';

const GRID_DURATION = 200; // 离屏网格缓存的过期时间(毫秒)
let gridCache: { off: HTMLCanvasElement; key: string; ts: number } | null = null;

function getGridCache(cols: number, rows: number, cell: number, theme: Theme): HTMLCanvasElement {
  const key = `${theme.id}-${cols}-${rows}-${cell}`;
  const now = performance.now();
  if (gridCache && gridCache.key === key && now - gridCache.ts < GRID_DURATION) {
    return gridCache.off;
  }
  const off = document.createElement('canvas');
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  off.width = cols * cell * dpr;
  off.height = rows * cell * dpr;
  off.style.width = `${cols * cell}px`;
  off.style.height = `${rows * cell}px`;
  const ctx = off.getContext('2d')!;
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, cols * cell, rows * cell);

  // 网格线
  ctx.strokeStyle = theme.grid;
  ctx.lineWidth = 1;
  for (let x = 0; x <= cols; x++) {
    ctx.beginPath();
    ctx.moveTo(x * cell + 0.5, 0);
    ctx.lineTo(x * cell + 0.5, rows * cell);
    ctx.stroke();
  }
  for (let y = 0; y <= rows; y++) {
    ctx.beginPath();
    ctx.moveTo(0, y * cell + 0.5);
    ctx.lineTo(cols * cell, y * cell + 0.5);
    ctx.stroke();
  }
  gridCache = { off, key, ts: now };
  return off;
}

function hexToRgb(hex: string): [number, number, number] {
  const m = hex.replace('#', '');
  const v = m.length === 3 ? m.split('').map((c) => c + c).join('') : m;
  const n = parseInt(v, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function lerpColor(a: [number, number, number], b: [number, number, number], t: number): string {
  const r = Math.round(a[0] + (b[0] - a[0]) * t);
  const g = Math.round(a[1] + (b[1] - a[1]) * t);
  const bl = Math.round(a[2] + (b[2] - a[2]) * t);
  return `rgb(${r}, ${g}, ${bl})`;
}

/**
 * 渲染一帧
 */
export function render(
  ctx: CanvasRenderingContext2D,
  canvas: HTMLCanvasElement,
  args: {
    cols: number;
    rows: number;
    cell: number;
    snake: Point[];
    food: Point;
    obstacles: Point[];
    direction: string;
    theme: Theme;
    time: number; // 累计秒数
  },
) {
  const { cols, rows, cell, snake, food, obstacles, direction, theme, time } = args;
  const w = cols * cell;
  const h = rows * cell;

  // 清屏
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // 背景渐变
  const bg = ctx.createLinearGradient(0, 0, w, h);
  // 从主题 bg 解析(支持 linear-gradient)
  const m = theme.bg.match(/linear-gradient\(([^)]+)\)/);
  if (m) {
    const parts = m[1].split(',').map((s) => s.trim());
    const stops: { pos: number; color: string }[] = [];
    parts.forEach((p) => {
      const pm = p.match(/(.+?)\s+(\d+)%/);
      if (pm) stops.push({ color: pm[1], pos: parseInt(pm[2], 10) / 100 });
    });
    if (stops.length >= 2) {
      stops.forEach((s) => bg.addColorStop(s.pos, s.color));
    } else {
      bg.addColorStop(0, '#0a0a1a');
      bg.addColorStop(1, '#1a0a2e');
    }
  }
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);

  // 网格
  const grid = getGridCache(cols, rows, cell, theme);
  ctx.drawImage(grid, 0, 0, w, h);

  // 扫描线动画
  const scanY = ((time * 0.05) % 1) * h;
  const scan = ctx.createLinearGradient(0, scanY - 30, 0, scanY + 30);
  scan.addColorStop(0, 'rgba(255,255,255,0)');
  scan.addColorStop(0.5, `${theme.accent}22`);
  scan.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = scan;
  ctx.fillRect(0, scanY - 30, w, 60);

  // 障碍
  if (obstacles.length) {
    ctx.save();
    ctx.shadowColor = theme.accent;
    ctx.shadowBlur = 12;
    ctx.fillStyle = `${theme.accent}55`;
    obstacles.forEach((o) => {
      const cx = o.x * cell + cell / 2;
      const cy = o.y * cell + cell / 2;
      ctx.beginPath();
      ctx.arc(cx, cy, cell * 0.35, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.restore();
  }

  // 食物(呼吸 + 旋转)
  const fx = food.x * cell + cell / 2;
  const fy = food.y * cell + cell / 2;
  const breath = 0.85 + Math.sin(time * 4) * 0.12;
  const rot = time * 1.5;
  ctx.save();
  ctx.translate(fx, fy);
  ctx.rotate(rot);
  ctx.shadowColor = theme.foodGlow;
  ctx.shadowBlur = 24;
  const foodGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, cell * 0.55);
  foodGrad.addColorStop(0, theme.food);
  foodGrad.addColorStop(1, `${theme.food}00`);
  ctx.fillStyle = foodGrad;
  ctx.beginPath();
  ctx.arc(0, 0, cell * 0.5 * breath, 0, Math.PI * 2);
  ctx.fill();
  // 内核高光
  ctx.shadowBlur = 0;
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(-cell * 0.1, -cell * 0.1, cell * 0.12, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // 蛇
  const headColor = hexToRgb(theme.snakeHead);
  const tailColor = hexToRgb(theme.snakeTail);
  const len = snake.length;
  snake.forEach((p, i) => {
    const t = len > 1 ? i / (len - 1) : 0;
    const color = lerpColor(headColor, tailColor, t);
    const cx = p.x * cell + cell / 2;
    const cy = p.y * cell + cell / 2;
    const radius = cell * 0.42 * (1 - t * 0.15);

    ctx.save();
    if (i === 0) {
      // 头部辉光
      ctx.shadowColor = theme.snakeHead;
      ctx.shadowBlur = 22;
    } else {
      ctx.shadowColor = color;
      ctx.shadowBlur = 8;
    }
    // 圆角矩形
    const x = cx - radius;
    const y = cy - radius;
    const r = radius * 0.55;
    ctx.fillStyle = color;
    roundRect(ctx, x, y, radius * 2, radius * 2, r);
    ctx.fill();
    // 高光
    ctx.shadowBlur = 0;
    ctx.fillStyle = 'rgba(255,255,255,0.18)';
    ctx.beginPath();
    ctx.ellipse(cx - radius * 0.25, cy - radius * 0.3, radius * 0.4, radius * 0.25, 0, 0, Math.PI * 2);
    ctx.fill();

    // 蛇头眼睛
    if (i === 0) {
      ctx.fillStyle = '#000';
      const eyeOffset = radius * 0.4;
      const eyeR = radius * 0.18;
      let ex1 = cx + eyeOffset;
      let ey1 = cy - eyeOffset * 0.4;
      let ex2 = cx + eyeOffset;
      let ey2 = cy + eyeOffset * 0.4;
      // 随方向调整眼睛位置
      if (direction === 'UP') {
        ex1 = cx - eyeOffset * 0.4;
        ex2 = cx + eyeOffset * 0.4;
        ey1 = cy - eyeOffset;
        ey2 = cy - eyeOffset;
      } else if (direction === 'DOWN') {
        ex1 = cx - eyeOffset * 0.4;
        ex2 = cx + eyeOffset * 0.4;
        ey1 = cy + eyeOffset;
        ey2 = cy + eyeOffset;
      } else if (direction === 'LEFT') {
        ex1 = cx - eyeOffset;
        ex2 = cx - eyeOffset;
        ey1 = cy - eyeOffset * 0.4;
        ey2 = cy + eyeOffset * 0.4;
      }
      ctx.beginPath();
      ctx.arc(ex1, ey1, eyeR, 0, Math.PI * 2);
      ctx.arc(ex2, ey2, eyeR, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  });

  // 粒子
  ctx.save();
  particlePool.alive.forEach((p) => {
    const a = Math.max(0, p.life / p.maxLife);
    ctx.globalAlpha = a;
    ctx.shadowColor = p.color;
    ctx.shadowBlur = 8;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size * a, 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.restore();
  ctx.globalAlpha = 1;
}

function roundRect(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

import { useEffect } from 'react';
import { useGameStore } from '../store/gameStore';
import type { Direction } from '../types';

const KEY_MAP: Record<string, Direction | 'PAUSE' | 'START' | 'RESET'> = {
  ArrowUp: 'UP',
  ArrowDown: 'DOWN',
  ArrowLeft: 'LEFT',
  ArrowRight: 'RIGHT',
  w: 'UP',
  W: 'UP',
  s: 'DOWN',
  S: 'DOWN',
  a: 'LEFT',
  A: 'LEFT',
  d: 'RIGHT',
  D: 'RIGHT',
  ' ': 'PAUSE',
  p: 'PAUSE',
  P: 'PAUSE',
  Enter: 'START',
};

export function useKeyboard() {
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const action = KEY_MAP[e.key];
      if (!action) return;

      const { status, setDirection, pause, resume, start, reset } = useGameStore.getState();

      // 防止方向键滚动页面
      if (e.key.startsWith('Arrow')) e.preventDefault();

      if (action === 'PAUSE') {
        if (status === 'playing') pause();
        else if (status === 'paused') resume();
        return;
      }
      if (action === 'START') {
        if (status === 'idle' || status === 'over') start();
        return;
      }
      if (action === 'RESET') {
        reset();
        return;
      }
      if (typeof action === 'string' && ['UP', 'DOWN', 'LEFT', 'RIGHT'].includes(action)) {
        if (status === 'playing') setDirection(action as Direction);
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, []);
}

import { useEffect, useRef } from 'react';
import { useGameStore } from '../store/gameStore';
import type { Direction } from '../types';

export function useTouch(ref: React.RefObject<HTMLElement | null>) {
  const touchStart = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const onStart = (e: TouchEvent) => {
      const t = e.touches[0];
      touchStart.current = { x: t.clientX, y: t.clientY };
    };

    const onEnd = (e: TouchEvent) => {
      if (!touchStart.current) return;
      const t = e.changedTouches[0];
      const dx = t.clientX - touchStart.current.x;
      const dy = t.clientY - touchStart.current.y;
      const absDx = Math.abs(dx);
      const absDy = Math.abs(dy);
      const THRESHOLD = 24;

      const { status, setDirection, start, pause, resume } = useGameStore.getState();
      if (status === 'idle' || status === 'over') {
        start();
        return;
      }
      if (status === 'paused') {
        resume();
        return;
      }
      if (status !== 'playing') return;

      if (Math.max(absDx, absDy) < THRESHOLD) {
        pause();
        return;
      }

      let dir: Direction;
      if (absDx > absDy) {
        dir = dx > 0 ? 'RIGHT' : 'LEFT';
      } else {
        dir = dy > 0 ? 'DOWN' : 'UP';
      }
      setDirection(dir);
      touchStart.current = null;
    };

    el.addEventListener('touchstart', onStart, { passive: true });
    el.addEventListener('touchend', onEnd, { passive: true });
    return () => {
      el.removeEventListener('touchstart', onStart);
      el.removeEventListener('touchend', onEnd);
    };
  }, [ref]);
}

