import { useEffect, useRef, useState } from 'react';
import { useGameStore } from '../store/gameStore';
import { THEMES } from '../game/themes';
import { render } from '../game/renderer';
import { particlePool, emitFoodBurst, emitSnakeTrail, emitAmbient } from '../game/particles';

export function GameCanvas() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const wrapperRef = useRef<HTMLDivElement | null>(null);
  const lastStepRef = useRef(0);
  const lastTimeRef = useRef(0);
  const lastTrailRef = useRef(0);
  const accumRef = useRef(0);
  const timeRef = useRef(0);
  const animRef = useRef<number>(0);
  const prevSnakeRef = useRef<{ x: number; y: number }[]>([]);
  const prevFoodRef = useRef<{ x: number; y: number } | null>(null);
  const [size, setSize] = useState({ w: 480, h: 480 });

  // 计算自适应大小
  useEffect(() => {
    const update = () => {
      const wrapper = wrapperRef.current;
      if (!wrapper) return;
      const rect = wrapper.getBoundingClientRect();
      // 保持正方形
      const s = Math.min(rect.width, rect.height, 720);
      setSize({ w: s, h: s });
    };
    update();
    const ro = new ResizeObserver(update);
    if (wrapperRef.current) ro.observe(wrapperRef.current);
    return () => ro.disconnect();
  }, []);

  // 主循环
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = size.w * dpr;
    canvas.height = size.h * dpr;
    canvas.style.width = `${size.w}px`;
    canvas.style.height = `${size.h}px`;
    ctx.scale(dpr, dpr);

    const cell = size.w / 24; // COLS = 24

    const tick = (now: number) => {
      const last = lastTimeRef.current || now;
      const dt = Math.min(0.05, (now - last) / 1000); // 防止 tab 切换跳变
      lastTimeRef.current = now;
      timeRef.current += dt;
      const s = useGameStore.getState();

      // 限时模式计时
      if (s.status === 'playing' && s.mode === 'timed') {
        s.tickTime(dt);
      }

      // 步进
      if (s.status === 'playing') {
        accumRef.current += dt * 1000;
        if (accumRef.current >= s.speedMs) {
          accumRef.current = 0;
          s.step();
        }
      } else {
        accumRef.current = 0;
      }

      // 粒子更新
      particlePool.update(dt);

      // 粒子触发:吃食物
      const cur = useGameStore.getState();
      if (cur.status === 'playing' && prevFoodRef.current) {
        const f = cur.food;
        if (f.x !== prevFoodRef.current.x || f.y !== prevFoodRef.current.y) {
          const px = (prevFoodRef.current.x + 0.5) * cell;
          const py = (prevFoodRef.current.y + 0.5) * cell;
          emitFoodBurst(px, py, THEMES[cur.theme].food, 28);
        }
      }
      prevFoodRef.current = { ...cur.food };

      // 蛇移动尾迹(每 60ms 一次)
      if (cur.status === 'playing' && now - lastTrailRef.current > 60) {
        lastTrailRef.current = now;
        if (cur.snake.length > 0) {
          const head = cur.snake[0];
          const px = (head.x + 0.5) * cell;
          const py = (head.y + 0.5) * cell;
          emitSnakeTrail(px, py, THEMES[cur.theme].snakeBody);
        }
      }

      // 背景环境粒子(随机)
      if (Math.random() < 0.15 && cur.status === 'playing') {
        const x = Math.random() * size.w;
        const y = size.h + 8;
        emitAmbient(x, y, THEMES[cur.theme].accent);
      }

      // 渲染
      render(ctx, canvas, {
        cols: cur.cols,
        rows: cur.rows,
        cell,
        snake: cur.snake,
        food: cur.food,
        obstacles: cur.obstacles,
        direction: cur.direction,
        theme: THEMES[cur.theme],
        time: timeRef.current,
      });

      // 重置变换(dpr 缩放)
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      prevSnakeRef.current = cur.snake;
      animRef.current = requestAnimationFrame(tick);
    };
    animRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(animRef.current);
  }, [size]);

  return (
    <div
      ref={wrapperRef}
      className="relative aspect-square w-full"
      style={{ maxWidth: `${size.w}px` }}
    >
      <div
        className="absolute inset-0 rounded-2xl"
        style={{
          background: THEMES[useGameStore.getState().theme].bg,
          boxShadow: `0 0 60px ${THEMES[useGameStore.getState().theme].accent}33, inset 0 0 30px ${THEMES[useGameStore.getState().theme].accent}11`,
        }}
      />
      <canvas
        ref={canvasRef}
        className="absolute inset-0 h-full w-full rounded-2xl"
        style={{ width: size.w, height: size.h }}
      />
    </div>
  );
}

